%[text] # 真实声学次级通路 ANC — 12kHz 降采样模型仿真
%[text] 被控对象: ARMAX(16,60,4,43) @ 12kHz (sim fit=89.9%, 22 NMP zeros)
%[text] 方法: Jafari F(z) + K(z,θ) — 固定FIR(H∞插值) + 自适应(NLMS)
%[text] 测试: 固定频率 / 线性扫频 / 非线性调频
%[text] 结构: Part 0 公共基础 → Parts 1/2/3 独立测试案例
clear; close all; clc;
scriptDir = fileparts(mfilename('fullpath'));
projectRoot = fileparts(scriptDir);
run(fullfile(projectRoot, 'project_init.m'));
%%
%[text] ## Part 0 · 问题总述与公共基础
%[text] 被控对象: 实测声学管道 ARMAX(16,60,4,43) @ 12kHz (4×降采样)
%[text] 22个非最小相位零点 → F(z) 频谱展平 → 固定 FIR(H∞插值)
%[text] 自适应: NLMS (μ=0.05, N=128) — 替代RLS以避免P矩阵在非平稳环境衰减
%% 0.1 模型加载
modelFile = fullfile(projectRoot, 'sysid_models', '20260706', ...
    'ARMAX_20260706_secpath_[16-60-4-43]_fs12k_sim90.mat');
load(modelFile, 'ARMAXmodel');

A = ARMAXmodel.model.A;             B_poly = ARMAXmodel.model.B;
d = ARMAXmodel.orders(4);           fs = ARMAXmodel.fs;
Ts = 1/fs;
B = B_poly(d+1:end);
nA = length(A)-1;  nB = length(B)-1;

fprintf('========== 12kHz 次级通路 ANC 仿真 ==========\n'); %[output:50cffe58]
fprintf('  模型: ARMAX(%d,%d,%d,%d), fs=%d Hz\n', ... %[output:group:226c8a87] %[output:310acb78]
    ARMAXmodel.orders(1), ARMAXmodel.orders(2), ARMAXmodel.orders(3), d, fs); %[output:group:226c8a87] %[output:310acb78]
fprintf('  极点: max|p|=%.4f,  零点: %d个NMP (max|z|=%.4f)\n', ... %[output:group:68a2334e] %[output:46b13ec5]
    max(abs(roots(A))), sum(abs(roots(B))>1), max(abs(roots(B)))); %[output:group:68a2334e] %[output:46b13ec5]
fprintf('  sim fit: %.1f%%n', ARMAXmodel.fit_sim); %[output:27a71fb7]

%% 0.2 F(z) 频谱展平
%[text] 步骤: 提取NMP零点 → 单位圆镜像反射(z→1/z̄) → 重构B̃(z)
%[text] F(z) = κ₀·L(z)·A(z⁻¹)/B̃(z⁻¹),  L(z) = (1-ρ)/(1-ρz⁻¹) 一阶低通
z_orig = roots(B);
z_nmp  = z_orig(abs(z_orig)>1);
z_mp   = z_orig(abs(z_orig)<=1);
B_tilde = real(poly([z_mp; 1./conj(z_nmp)]));
B_tilde = B_tilde * (B(1)/B_tilde(1));
rho = exp(-2*pi*1000*Ts);   % LPF cutoff = 1kHz (12kHz fs → 合理通带)
L_num = 1-rho;  L_den = [1, -rho];

F_num = A;
F_den = conv(L_den, B_tilde);
F_den = F_den / F_den(1);
nF_num = length(F_num);  nF_den = length(F_den);

H_num = conv([zeros(1,d), B], F_num);
H_den = conv(A, F_den);

fprintf('  F(z): %d个NMP零点反射+1阶LPF(1kHz), 阶次 num=%d/den=%d\n', ... %[output:group:6fb819ea] %[output:63cb61bf]
    length(z_nmp), nF_num-1, nF_den-1); %[output:group:6fb819ea] %[output:63cb61bf]
%% 0.3 固定控制器 (设计频率 = 第一共振峰 ≈ 265 Hz)
%[text] FIR K(z,θ)=Σθᵢz⁻ⁱ, N=200. 插值约束: G\_eff(e^{jω₀})·K(e^{jω₀})=1
%[text] 注: 次级通路首峰增益约 -6.8 dB，控制器需补偿此衰减
w_scan = linspace(0.001, pi, 8000);
G_scan = abs(freqz(B, A, w_scan));
[pks, locs] = findpeaks(G_scan, 'MinPeakHeight', 0.05, 'MinPeakDistance', 30);
f_peaks = w_scan(locs)*fs/(2*pi);

% 选取有实际意义的低频共振峰（优先 < 1kHz）
f_low = f_peaks(f_peaks < 1000);
if ~isempty(f_low)
    f0 = f_low(1);
else
    f0 = f_peaks(1);
end
omega0 = 2*pi*f0/fs;

N_fir = 200;
zi0 = exp(1j*omega0);
G_eff_0 = polyval_freqz(H_num, H_den, omega0);
Aeq = [real(G_eff_0*zi0.^(-(0:N_fir-1))); imag(G_eff_0*zi0.^(-(0:N_fir-1)))];
theta_fixed = Aeq \ [1; 0];

Nfreq = 2000;  w_grid = linspace(0, pi, Nfreq);
G_eff_grid = freqz(H_num, H_den, w_grid).';
gamma_fixed = max(abs(G_eff_grid(:).*(exp(-1j*(0:N_fir-1)'.*w_grid)'*theta_fixed)));

fprintf('  固定FIR: f0=%.1fHz, N=%d, ||θ||=%.2f, γ=%.4f\n', ... %[output:group:6a336800] %[output:9269b07b]
    f0, N_fir, norm(theta_fixed), gamma_fixed); %[output:group:6a336800] %[output:9269b07b]
%[text] 被控对象差分方程 + 固定/自适应仿真句柄
%% 0.4 仿真引擎
a_plant = A;  b_plant = [zeros(1,d), B];  Lb = length(b_plant);
k_start = max(N_fir, nA+Lb) + 1;

rms_win = @(y, t1, t2) rms(y(round(t1*fs):round(t2*fs)));
supp_db = @(y_o, y_c, t1, t2) 20*log10(rms_win(y_o, t1, t2)/max(rms_win(y_c, t1, t2), 1e-10));

sim_fixed = @(d_sig, Tsim) sim_fixed_impl(d_sig, Tsim, fs, Ts, N_fir, theta_fixed, ...
    a_plant, b_plant, nA, Lb, nF_num, nF_den, F_num, F_den, k_start);
sim_nlms  = @(d_sig, Tsim, N_adapt, mu) sim_nlms_impl(d_sig, Tsim, fs, Ts, N_adapt, mu, ...
    a_plant, b_plant, nA, Lb, nF_num, nF_den, F_num, F_den, H_num, H_den, k_start);
sim_imc_lms = @(d_sig, Tsim, N_lms, mu_lms) sim_imc_lms_impl(d_sig, Tsim, fs, Ts, N_lms, mu_lms, ...
    a_plant, b_plant, nA, Lb, k_start);

fprintf('\n========== 公共基础完成 ==========\n\n'); %[output:2d0f85a8]
%%
%[text] ## Part 1 · 固定频率扰动 — 稳态性能验证
%[text] 问题: 单频正弦扰动 @ 共振峰频率 f₀≈265Hz, |G₀|≈-6.8dB
%[text] 目标: 验证 F(z)+K(z) 在理想条件下的降噪能力
%[text] 对比: 开环 vs 固定FIR vs 自适应NLMS
%% 1.1 扰动设计
Tsim1 = 8;  Nsim1 = round(Tsim1*fs);  t1 = (0:Nsim1-1)*Ts;
rng(42);
d1 = 0.6*sin(2*pi*f0*t1) + 0.02*randn(1, Nsim1);
d1 = d1/max(abs(d1))*0.8;
y_open1 = filter(b_plant, a_plant, d1);

%% 1.2 固定控制器
y_fix1 = sim_fixed(d1, Tsim1);
supp_f1 = supp_db(y_open1, y_fix1, 2, Tsim1);

%% 1.3 自适应 NLMS (Jafari: F(z)+H(z))
[y_nlms1, th1] = sim_nlms(d1, Tsim1, 128, 0.05);
supp_a1 = supp_db(y_open1, y_nlms1, 2, Tsim1);

%% 1.4 IMC-FXNLMS 退化基线 (无F/H)
[y_imc1, w_imc1] = sim_imc_lms(d1, Tsim1, 128, 0.05);
supp_imc1 = supp_db(y_open1, y_imc1, 2, Tsim1);

%% 1.5 报告与图解
fprintf('--- Part 1: 固定频率 %.0f Hz ---\n', f0); %[output:05d841e5]
fprintf('  固定(N=%d):            %.1f dB\n', N_fir, supp_f1); %[output:6981124d]
fprintf('  Jafari NLMS(N=%d,μ=%.2f): %.1f dB  ||θ||=%.1f\n', 128, 0.05, supp_a1, norm(th1(:,end))); %[output:25e38621]
fprintf('  IMC-FXNLMS (N=%d,μ=%.2f): %.1f dB  ||w||=%.1f\n', 128, 0.05, supp_imc1, norm(w_imc1(:,end))); %[output:188428f3]

figure('Name', 'Part1: 固定频率'); %[output:55baef68]
subplot(2,1,1); %[output:55baef68]
plot(t1, y_open1, 'Color', [.7 .7 .7]); hold on; %[output:55baef68]
plot(t1, y_fix1, 'r-', 'LineWidth', 1); %[output:55baef68]
plot(t1, y_nlms1, 'b-', 'LineWidth', 1); %[output:55baef68]
plot(t1, y_imc1, 'Color', [0.8 0.4 0], 'LineWidth', 1); %[output:55baef68]
legend('开环', sprintf('固定 %.1fdB', supp_f1), ... %[output:55baef68]
    sprintf('Jafari NLMS %.1fdB', supp_a1), sprintf('IMC-FXNLMS %.1fdB', supp_imc1)); %[output:55baef68]
title(sprintf('固定频率 %.0f Hz', f0));  xlim([4 4.5]);  grid on; %[output:55baef68]
subplot(2,1,2); %[output:55baef68]
nfft_psd = min(2048, Nsim1);
[Po, fp] = pwelch(y_open1(end-nfft_psd:end), hann(1024), 512, 2048, fs);
[Pc, ~]  = pwelch(y_fix1(end-nfft_psd:end),  hann(1024), 512, 2048, fs);
[Pa, ~]  = pwelch(y_nlms1(end-nfft_psd:end), hann(1024), 512, 2048, fs);
[Pi, ~]  = pwelch(y_imc1(end-nfft_psd:end),  hann(1024), 512, 2048, fs);
semilogy(fp, Po, 'Color', [.7 .7 .7]); hold on; %[output:55baef68]
semilogy(fp, Pc, 'r-');  semilogy(fp, Pa, 'b-'); %[output:55baef68]
semilogy(fp, Pi, 'Color', [0.8 0.4 0]); %[output:55baef68]
xlim([0 1000]);  legend('开环', '固定', 'Jafari NLMS', 'IMC-FXNLMS'); %[output:55baef68]
title('稳态 PSD');  xlabel('Hz');  grid on; %[output:55baef68]
sgtitle('Part 1: 固定频率扰动 — 稳态性能验证'); %[output:55baef68]
fprintf('\n');
%%
%[text] ## Part 2 · 线性扫频扰动 — 跟踪能力验证
%[text] 问题: f(t) = 230 + 70·t/Tsim Hz, 线性扫过 230→300 Hz
%[text] 关键: 固定控制器设计在 f₀≈265Hz — 偏离时性能退化
%[text] NLMS 应跟踪频率变化，维持全频段抑制
%% 2.1 扰动设计
Tsim2 = 8;  Nsim2 = round(Tsim2*fs);  t2 = (0:Nsim2-1)*Ts;
f_start2 = max(50, f0 - 35);
f_end2   = min(fs/2 * 0.8, f0 + 35);
f_inst2 = f_start2 + (f_end2 - f_start2)*t2/Tsim2;
phase2  = 2*pi*(f_start2*t2 + (f_end2 - f_start2)*t2.^2/(2*Tsim2));
rng(42);  d2 = 0.6*sin(phase2) + 0.02*randn(1, Nsim2);
d2 = d2/max(abs(d2))*0.8;
y_open2 = filter(b_plant, a_plant, d2);

%% 2.2 固定控制器
y_fix2 = sim_fixed(d2, Tsim2);

%% 2.3 自适应 NLMS (Jafari)
[y_nlms2, ~] = sim_nlms(d2, Tsim2, 128, 0.05);

%% 2.4 IMC-FXNLMS 退化基线
[y_imc2, ~] = sim_imc_lms(d2, Tsim2, 128, 0.05);

%% 2.5 分段对比
fprintf('--- Part 2: 线性扫频 %.0f→%.0f Hz ---\n', f_start2, f_end2); %[output:87116b44]
fprintf('  %8s %10s %12s %12s %12s\n', 't(s)', 'f(Hz)', '固定(dB)', 'J.NLMS(dB)', 'IMC-FXNLMS(dB)'); %[output:9f951899]
t_chk = 2:0.5:Tsim2-0.5;
supp_f2 = zeros(size(t_chk));  supp_a2 = zeros(size(t_chk));  supp_imc2 = zeros(size(t_chk));
for i = 1:length(t_chk) %[output:group:5a783e11]
    tc = t_chk(i);
    supp_f2(i) = supp_db(y_open2, y_fix2,  tc-0.25, tc+0.25);
    supp_a2(i) = supp_db(y_open2, y_nlms2, tc-0.25, tc+0.25);
    supp_imc2(i) = supp_db(y_open2, y_imc2, tc-0.25, tc+0.25);
    fc = f_start2 + (f_end2 - f_start2)*tc/Tsim2;
    fprintf('  %8.1f %10.1f %12.1f %12.1f %12.1f\n', tc, fc, supp_f2(i), supp_a2(i), supp_imc2(i)); %[output:7891bb0d]
end %[output:group:5a783e11]
fprintf('  早期(2-3s): 固定 %.1fdB  J.NLMS %.1fdB  IMC-FXNLMS %.1fdB\n', ... %[output:group:52c03e51] %[output:4255da28]
    mean(supp_f2(1:3)), mean(supp_a2(1:3)), mean(supp_imc2(1:3))); %[output:group:52c03e51] %[output:4255da28]
fprintf('  晚期(6-7s): 固定 %.1fdB  J.NLMS %.1fdB  IMC-FXNLMS %.1fdB\n', ... %[output:group:4b345b3e] %[output:549fa004]
    mean(supp_f2(end-2:end)), mean(supp_a2(end-2:end)), mean(supp_imc2(end-2:end))); %[output:group:4b345b3e] %[output:549fa004]

figure('Name', 'Part2: 线性扫频'); %[output:628352ae]
subplot(2,1,1); %[output:628352ae]
plot(t2, y_open2, 'Color', [.7 .7 .7]); hold on; %[output:628352ae]
plot(t2, y_fix2, 'r-', 'LineWidth', .8); %[output:628352ae]
plot(t2, y_nlms2, 'b-', 'LineWidth', 1); %[output:628352ae]
plot(t2, y_imc2, 'Color', [0.8 0.4 0], 'LineWidth', 1); %[output:628352ae]
legend('开环', '固定', 'Jafari NLMS', 'IMC-FXNLMS');  xlim([1 Tsim2]); %[output:628352ae]
title(sprintf('扫频 %.0f→%.0f Hz (%.1f Hz/s)', f_start2, f_end2, (f_end2-f_start2)/Tsim2));  grid on; %[output:628352ae]
subplot(2,1,2); %[output:628352ae]
plot(t_chk, supp_f2, 'r-o', 'LineWidth', 1.3);  hold on; %[output:628352ae]
plot(t_chk, supp_a2, 'b-s', 'LineWidth', 1.3); %[output:628352ae]
plot(t_chk, supp_imc2, 'Color', [0.8 0.4 0], 'Marker', '^', 'LineWidth', 1.3);  yline(0, 'k-'); %[output:628352ae]
xlabel('t(s)');  ylabel('抑制(dB)');  legend('固定', 'Jafari NLMS', 'IMC-FXNLMS');  grid on; %[output:628352ae]
title(sprintf('分段抑制 (设计频率 %.0f Hz)', f0)); %[output:628352ae]
sgtitle('Part 2: 线性扫频扰动 — 跟踪能力验证'); %[output:628352ae]
fprintf('\n');
%%
%[text] ## Part 3 · 非线性调频扰动 — 频率反转测试
%[text] 问题: f(t) = f₀ + 30·sin(2π·1.5·t) Hz, 正弦调制
%[text] 关键: 频率方向周期性反转 — 最严苛的NLMS跟踪测试
%% 3.1 扰动设计
Tsim3 = 10;  Nsim3 = round(Tsim3*fs);  t3 = (0:Nsim3-1)*Ts;
f0_fm = f0;  df_fm = 30;  fm = 1.5;
f_inst3 = f0_fm + df_fm*sin(2*pi*fm*t3);
phase3  = 2*pi*f0_fm*t3 - (df_fm/fm)*cos(2*pi*fm*t3);
rng(42);  d3 = 0.6*sin(phase3) + 0.02*randn(1, Nsim3);
d3 = d3/max(abs(d3))*0.8;
y_open3 = filter(b_plant, a_plant, d3);

%% 3.2 固定控制器
y_fix3 = sim_fixed(d3, Tsim3);

%% 3.3 自适应 NLMS (Jafari)
[y_nlms3, ~] = sim_nlms(d3, Tsim3, 128, 0.05);

%% 3.4 IMC-FXNLMS 退化基线
[y_imc3, ~] = sim_imc_lms(d3, Tsim3, 128, 0.05);

%% 3.5 分段对比
fprintf('--- Part 3: 正弦FM %.0f±%d Hz ---\n', f0_fm, df_fm); %[output:497ed013]
fprintf('  %8s %10s %12s %12s %12s\n', 't(s)', 'f(Hz)', '固定(dB)', 'J.NLMS(dB)', 'IMC-FX(dB)'); %[output:31fcf06b]
t_chk3 = 2:0.5:Tsim3-0.5;
for i = 1:length(t_chk3) %[output:group:69381b5f]
    tc = t_chk3(i);
    sf = supp_db(y_open3, y_fix3,  tc-0.25, tc+0.25);
    sa = supp_db(y_open3, y_nlms3, tc-0.25, tc+0.25);
    si = supp_db(y_open3, y_imc3,  tc-0.25, tc+0.25);
    fprintf('  %8.1f %10.1f %12.1f %12.1f %12.1f\n', tc, f0_fm+df_fm*sin(2*pi*fm*tc), sf, sa, si); %[output:01897a86]
end %[output:group:69381b5f]

%% 3.6 图解
figure('Name', 'Part3: 非线性FM'); %[output:96bdf447]
subplot(2,2,[1 2]); %[output:96bdf447]
plot(t3, y_open3, 'Color', [.7 .7 .7]); hold on; %[output:96bdf447]
plot(t3, y_fix3, 'r-', 'LineWidth', .7); %[output:96bdf447]
plot(t3, y_nlms3, 'b-', 'LineWidth', 1); %[output:96bdf447]
plot(t3, y_imc3, 'Color', [0.8 0.4 0], 'LineWidth', 1); %[output:96bdf447]
legend('开环', '固定', 'Jafari NLMS', 'IMC-FXNLMS');  xlim([1 Tsim3]); %[output:96bdf447]
title(sprintf('正弦FM: %.0f±%d Hz @ %.1f Hz 调制', f0_fm, df_fm, fm));  grid on; %[output:96bdf447]

subplot(2,2,3); %[output:96bdf447]
plot(t3, f_inst3, 'k-', 'LineWidth', 1);  hold on; %[output:96bdf447]
yline(f0, 'r--', '设计频率'); %[output:96bdf447]
xlabel('t(s)');  ylabel('f(Hz)');  title('瞬时频率');  grid on;  xlim([1 Tsim3]); %[output:96bdf447]

subplot(2,2,4); %[output:96bdf447]
t_rev = 1/fm*0.75 + 2;  idx = round((t_rev-0.05)*fs):round((t_rev+0.05)*fs);
if idx(end) <= Nsim3
    plot(t3(idx), y_open3(idx), 'Color', [.7 .7 .7]); hold on; %[output:96bdf447]
    plot(t3(idx), y_fix3(idx), 'r-'); %[output:96bdf447]
    plot(t3(idx), y_nlms3(idx), 'b-', 'LineWidth', 1.2); %[output:96bdf447]
    plot(t3(idx), y_imc3(idx), 'Color', [0.8 0.4 0], 'LineWidth', 1.2); %[output:96bdf447]
    legend('开环', '固定', 'Jafari NLMS', 'IMC-FXNLMS'); %[output:96bdf447]
end
title(sprintf('频率反转处 (t≈%.1fs)', t_rev));  grid on; %[output:96bdf447]
sgtitle('Part 3: 非线性调频扰动 — 频率反转测试'); %[output:96bdf447]

fprintf('\n========== Part 1-3 完成 ==========\n'); %[output:6ddfca3f]

%%
%[text] ## Part 4 · IMC-FXNLMS 综合对比总结
%[text] 对比矩阵 (全部使用相同 IMC, μ₀=0.05, N=128, NLMS 归一化):
%[text]   Jafari:     regressor φ = H(z)\[z\] = G₀\*F(z)\[z\]  (含 F 频谱展平)
%[text]   IMC-FXNLMS: regressor φ = G₀(z)\[z\]              (仅次级通路滤波)
%[text]   差异维度:   F(z) 频谱展平 + 由此带来的 H(z) 差异
%% 4.1 各工况抑制量汇总
fprintf('\n========== Part 4: IMC-FXNLMS 综合对比总结 ==========\n'); %[output:80de9854]
fprintf('  %-20s %10s %10s %10s %10s\n', '工况', '固定FIR', 'Jafari NLMS', 'IMC-FXNLMS', 'Δ(J−FX)'); %[output:857960a1]
fprintf('  %-20s %10s %10s %10s %10s\n', '----', '------', '----------', '----------', '--------'); %[output:5f4668ce]
fprintf('  %-20s %9.1fdB %9.1fdB %9.1fdB %+9.1fdB\n', ... %[output:group:9e2b195a] %[output:96f45cb1]
    sprintf('Part1 固定 %.0fHz', f0), supp_f1, supp_a1, supp_imc1, supp_a1-supp_imc1); %[output:group:9e2b195a] %[output:96f45cb1]
fprintf('  %-20s %9.1fdB %9.1fdB %9.1fdB %+9.1fdB\n', ... %[output:group:7de32d09] %[output:48635b62]
    sprintf('Part2 扫频 %.0f-%.0fHz', f_start2, f_end2), ... %[output:48635b62]
    mean(supp_f2), mean(supp_a2), mean(supp_imc2), mean(supp_a2)-mean(supp_imc2)); %[output:group:7de32d09] %[output:48635b62]
