%%
%[text] ## 辅助函数
%[text] sim\_fixed\_impl: 固定FIR控制器仿真循环 (IMC + F(z))
%[text] sim\_nlms\_impl:  NLMS自适应控制器仿真循环 (IMC + F(z) + G₀F滤波回归)
%[text] sim\_imc\_lms\_impl:  IMC-FXNLMS 仿真循环 (IMC + G₀滤波回归 + NLMS, 无F展平)

function y = sim_fixed_impl(d_sig, Tsim, fs, Ts, N_fir, theta_fixed, ...
        a_plant, b_plant, nA, Lb, nF_num, nF_den, F_num, F_den, k_start)
    Nsim = round(Tsim*fs);  t = (0:Nsim-1)*Ts;
    y = zeros(1,Nsim);  u = zeros(1,Nsim);  g = zeros(1,Nsim);  z = zeros(1,Nsim);
    xF = zeros(nF_num, 1);  yF = zeros(nF_den-1, 1);
    for k = k_start:Nsim
        g(k) = -a_plant(2:end)*g(k-1:-1:k-nA)' + b_plant*u(k-1:-1:k-Lb)';
        y(k) = g(k) + d_sig(k);  z(k) = y(k) - g(k);
        if t(k) >= 2
            v = theta_fixed'*z(k-(1:N_fir))';
            xF = [v; xF(1:nF_num-1)];
            uk = F_num*xF - F_den(2:end)*yF;
            yF = [uk; yF(1:nF_den-2)];
            u(k) = -uk;
            if isnan(u(k)) || abs(u(k)) > 1e4, u(k) = 0; end
        end
    end
end

function [y, th] = sim_nlms_impl(d_sig, Tsim, fs, Ts, N_adapt, mu, ...
        a_plant, b_plant, nA, Lb, nF_num, nF_den, F_num, F_den, H_num, H_den, k_start)
    Nsim = round(Tsim*fs);  t = (0:Nsim-1)*Ts;
    y = zeros(1,Nsim);  u = zeros(1,Nsim);  g = zeros(1,Nsim);  z = zeros(1,Nsim);
    zf = zeros(1,Nsim);  th = zeros(N_adapt, Nsim);  theta = zeros(N_adapt, 1);
    xF = zeros(nF_num, 1);  yF = zeros(nF_den-1, 1);
    xH = zeros(length(H_num)-1, 1);  yH = zeros(length(H_den)-1, 1);
    for k = k_start:Nsim
        g(k) = -a_plant(2:end)*g(k-1:-1:k-nA)' + b_plant*u(k-1:-1:k-Lb)';
        y(k) = g(k) + d_sig(k);  z(k) = y(k) - g(k);
        xH = [z(k); xH(1:end-1)];
        zf(k) = H_num(2:end)*xH - H_den(2:end)*yH;
        yH = [zf(k); yH(1:end-1)];
        if t(k) < 2, continue; end
        if k > N_adapt, phi = zf(k-(1:N_adapt))'; else, phi = zeros(N_adapt, 1); end
        e = z(k) - theta'*phi;
        theta = theta + mu*e*phi/(phi'*phi + 0.01);
        th(:, k) = theta;
        v = theta'*z(k-(1:N_adapt))';
        xF = [v; xF(1:nF_num-1)];
        uk = F_num*xF - F_den(2:end)*yF;
        yF = [uk; yF(1:nF_den-2)];
        u(k) = -uk;
        if isnan(u(k)) || abs(u(k)) > 1e4, u(k) = 0; end
    end
end

function [y, w_hist] = sim_imc_lms_impl(d_sig, Tsim, fs, Ts, N_lms, mu, ...
        a_plant, b_plant, nA, Lb, k_start)
% IMC-FXNLMS 退化基线 — IMC 架构 + Filtered-X NLMS (无 F(z) 展平)
%   扰动估计: z(k) = y(k) − ĝ(k),  ĝ(k) = G₀(z)[u(k−1)]
%   滤波参考: zf(k) = G₀(z)[z(k)]  ← Filtered-X: 补偿次级通路延迟/动态
%   控制器:   u(k) = −θᵀ·z_delays(k)   (原始 z, 不经 F(z))
%   NLMS回归: φ(k) = zf_delays(k)      (G₀ 滤波后的 z)
%   NLMS更新: e=z(k)−θᵀ·φ, θ←θ + μ·e·φ/(φ'·φ+ε)
%
%   与 Jafari NLMS 对比:
%     Jafari:  φ = H(z)[z] = G₀*F(z)[z]  (滤波含 F 展平)
%     IMC-FX:  φ = G₀(z)[z]              (仅次级通路滤波, 无 F)

    Nsim = round(Tsim*fs);
    t = (0:Nsim-1)*Ts;
    y = zeros(1,Nsim);          % 误差传声器信号
    u = zeros(1,Nsim);          % 控制器输出 (直接进入 plant, 无 F(z))
    g = zeros(1,Nsim);          % 次级通路输出 (抵消声波)
    z = zeros(1,Nsim);          % IMC 扰动估计
    zf = zeros(1,Nsim);         % Filtered-X: z 经 G₀(z) 滤波
    theta = zeros(N_lms, 1);    % NLMS 权值向量
    w_hist = zeros(N_lms, Nsim);
    eps_nlms = 0.01;            % 归一化常数, 与 Jafari NLMS 一致

    % G₀(z) 滤波缓冲区 (用于 Filtered-X)
    xG_buf = zeros(1, Lb);      % 滤波器输入历史
    yG_buf = zeros(1, nA);      % 滤波器输出历史

    for k = k_start:Nsim
        % --- 步骤1: 次级通路输出 g(k) = G₀(z)[u(k-1)] ---
        g(k) = -a_plant(2:end)*g(k-1:-1:k-nA)' + b_plant*u(k-1:-1:k-Lb)';

        % --- 步骤2: 误差传声器 + 扰动估计 (IMC) ---
        y(k) = g(k) + d_sig(k);
        z(k) = y(k) - g(k);     % IMC: z(k) = y − ĝ ≈ d(k)

        % --- 步骤3: Filtered-X — z 经 G₀(z) 预滤波 ---
        % 模拟: 「如果 z(k) 作为抗噪声通过 plant, 误差传声器收到什么?」
        % 这是 FXLMS 的核心: 用滤波后的参考做 LMS 回归量
        xG_buf = [z(k), xG_buf(1:Lb-1)];
        zf(k) = -a_plant(2:end)*yG_buf' + b_plant*xG_buf';
        yG_buf = [zf(k), yG_buf(1:nA-1)];

        if t(k) >= 2
            % --- 步骤4: 控制器 u(k) = −θᵀ·z_delays (原始 z, 不经 F) ---
            z_delays = z(k-(1:N_lms))';
            u(k) = -theta' * z_delays;

            % --- 步骤5: NLMS 权值更新 (用 G₀ 滤波回归量 φ=zf_delays) ---
            % 对比 Jafari: Jafari 的 φ 额外经 F(z) 展平 + H(z) 滤波
            % 此处 φ 仅经 G₀(z) 滤波 (标准 Filtered-X)
            phi = zf(k-(1:N_lms))';
            e_pred = z(k) - theta' * phi;
            theta = theta + mu * e_pred * phi / (phi'*phi + eps_nlms);

            % 安全保护
            if isnan(u(k)) || abs(u(k)) > 1e4
                u(k) = 0;
            end
        end

        w_hist(:, k) = theta;
    end
end

function v = polyval_freqz(num, den, w)
    v = sum(num.*exp(-1j*w*(0:length(num)-1))) / sum(den.*exp(-1j*w*(0:length(den)-1)));
end

